class NumMatrix:
    def __init__(self, matrix):
        self.rows = len(matrix)
        self.cols = len(matrix[0])
        self.matrix = [row[:] for row in matrix]
        self.bit = [[0] * (self.cols + 1) for _ in range(self.rows + 1)]
        for r in range(self.rows):
            for c in range(self.cols):
                self._add(r, c, matrix[r][c])

    def _add(self, r, c, delta):
        i = r + 1
        while i <= self.rows:
            j = c + 1
            while j <= self.cols:
                self.bit[i][j] += delta
                j += j & (-j)
            i += i & (-i)

    def _prefix(self, r, c):
        if r < 0 or c < 0:
            return 0
        s = 0
        i = r + 1
        while i > 0:
            j = c + 1
            while j > 0:
                s += self.bit[i][j]
                j -= j & (-j)
            i -= i & (-i)
        return s

    def update(self, row, col, val):
        delta = val - self.matrix[row][col]     # adjust by just the change
        self.matrix[row][col] = val
        self._add(row, col, delta)

    def sum_region(self, row1, col1, row2, col2):
        return (self._prefix(row2, col2) - self._prefix(row1 - 1, col2)
                - self._prefix(row2, col1 - 1) + self._prefix(row1 - 1, col1 - 1))   # 4-corner inclusion-exclusion

