#include <bits/stdc++.h>
using namespace std;

class NumMatrix {
public:
    int rows, cols;
    vector<vector<int>> matrix, bit;

    NumMatrix(vector<vector<int>>& matrix) : matrix(matrix) {
        rows = matrix.size(); cols = matrix[0].size();
        bit.assign(rows + 1, vector<int>(cols + 1, 0));
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) {
                int val = matrix[r][c];
                this->matrix[r][c] = 0;
                update(r, c, val);
            }
    }

    void add(int r, int c, int delta) {
        for (int i = r + 1; i <= rows; i += i & (-i))
            for (int j = c + 1; j <= cols; j += j & (-j))
                bit[i][j] += delta;
    }

    int prefix(int r, int c) {
        if (r < 0 || c < 0) return 0;
        int s = 0;
        for (int i = r + 1; i > 0; i -= i & (-i))
            for (int j = c + 1; j > 0; j -= j & (-j))
                s += bit[i][j];
        return s;
    }

    void update(int row, int col, int val) {
        int delta = val - matrix[row][col];         // adjust by just the change
        matrix[row][col] = val;
        add(row, col, delta);
    }

    int sumRegion(int row1, int col1, int row2, int col2) {
        return prefix(row2, col2) - prefix(row1 - 1, col2)
             - prefix(row2, col1 - 1) + prefix(row1 - 1, col1 - 1);     // 4-corner inclusion-exclusion
    }
};
